      "probability": 0.30
    },
    {
      "tone": "cordial",
      "text": "Com certeza! Avaliaremos organização, conteúdo, criatividade e cumprimento dos prazos estipulados para o trabalho.",
      "probability": 0.25
    },
    {
      "tone": "objetivo",
      "text": "Os critérios são: qualidade do conteúdo, estrutura, relevância e conformidade com as instruções fornecidas.",
      "probability": 0.20
    },
    {
      "tone": "gentil",
      "text": "Vou detalhar os critérios: coerência, profundidade, formato e originalidade para que possa ajustar seu trabalho.",
      "probability": 0.15
    },
    {
      "tone": "empatico",
      "text": "Entendo sua preocupação! Avaliaremos clareza, argumentação, criatividade e aderência às orientações para ajudar você.",
      "probability": 0.10
    }
  ]
}

